import sys

def main():
    import sys
    s = sys.stdin.readline().strip()
    t = sys.stdin.readline().strip()
    t_index = 0
    used = [False] * len(s)

    for i in range(len(s)):
        if t_index < len(t) and s[i] == t[t_index]:
            used[i] = True
            t_index += 1

    if all(used):
        print("Yes")
    else:
        print("No")

main()
